app.post('/api/diagnose',async(req,res)=>{const s=await requireUser(req,res);if(!s)return;try{const input=z.object({repo:z.object({owner:z.string().min(1),name:z.string().min(1),defaultBranch:z.string().optional()}),logs:z.string().max(22000).optional(),manual:z.boolean().optional(),category:z.enum(['build','dependencies','typescript','configuration','security','runtime']).nullable().optional()}).parse(req.body);const balance=await getCredits(s.user.id);if(balance.credits<10)throw Error('Not enough credits. Buy a pack to continue.');const context=await repoContext(s,input.repo.owner,input.repo.name);const prompt=`You are a careful senior engineer diagnosing a repository. Return ONLY JSON {"summary":"plain language summary","issues":[{"category":"build|dependencies|typescript|configuration|security|runtime","severity":"critical|high|medium|low|info","title":"short title","details":"evidence-based explanation","filePath":"path or empty","fixSummary":"small proposed fix","confidence":0.0}]}. Only report findings supported by evidence. Maximum 10 findings. Don't invent runtime failures from source alone, include no secrets, don't claim tests/builds were run, distinguish likely causes from confirmed causes, and use plain language.\nRepository ${input.repo.owner}/${input.repo.name}; default branch ${context.branch}.\nFiles: ${JSON.stringify(context.files)}\nRedacted Vercel logs: ${redactSecrets(input.logs||'No logs supplied')}\nManual checks: ${!!input.manual}. Focus category: ${input.category||'all categories'}. If a focus category is supplied, only return findings in that category. If no issues are supported by evidence for that category, return an empty issues array and explain that no issue was confirmed.`;const {result,cost}=await chargedModelJson(prompt,{userId:s.user.id,amount:10,reason:'AI diagnosis',metadata:{repo:`${input.repo.owner}/${input.repo.name}`},req});const issues=(Array.isArray(result.issues)?result.issues:[]).slice(0,10).filter(i=>!input.category||i.category===input.category).map(i=>({category:['build','dependencies','typescript','configuration','security','runtime'].includes(i.category)?i.category:'configuration',severity:['critical','high','medium','low','info'].includes(i.severity)?i.severity:'medium',title:String(i.title||'Potential issue').slice(0,180),details:String(i.details||'No details provided.').slice(0,1500),filePath:String(i.filePath||'').slice(0,240),fixSummary:String(i.fixSummary||'Review the relevant code and deployment evidence.').slice(0,1000),confidence:Math.max(0,Math.min(1,Number(i.confidence)||.5))}));if(supabase)await supabase.from('repair_tasks').insert({github_id:String(s.user.id),repo_full_name:`${input.repo.owner}/${input.repo.name}`,kind:input.manual?'manual_diagnosis':'diagnosis',status:'complete',summary:String(result.summary||'Diagnosis complete'),report:{issues,category:input.category||null},credits_spent:10});res.json({summary:String(result.summary||'Diagnosis complete; review findings below.'),issues,branch:context.branch,filesInspected:context.files.map(f=>f.path),creditsSpent:10,creditsRemaining:cost.credits,demo:cost.demo,checkedAt:new Date().toISOString()})}catch(e){err(res,e,e instanceof z.ZodError?422:400)}});
function xmlEscape(value){return String(value??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;')}
function parseCsvRows(input){const rows=[];let row=[],cell='',quoted=false;const t=String(input||'');for(let i=0;i<t.length;i++){const c=t[i];if(c==='"'){if(quoted&&t[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&t[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v!==''))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(v=>v!==''))rows.push(row);return rows.slice(0,500).map(r=>r.slice(0,40))}
function columnName(n){let out='';while(n>0){const r=(n-1)%26;out=String.fromCharCode(65+r)+out;n=Math.floor((n-1)/26)}return out}
async function makeDocx(text){const zip=new JSZip(),paras=String(text||'').replace(/\r/g,'').split('\n').slice(0,400).map(line=>`<w:p><w:r><w:t xml:space="preserve">${xmlEscape(line||' ')}</w:t></w:r></w:p>`).join('');zip.file('[Content_Types].xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>');zip.file('_rels/.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>');zip.file('word/document.xml',`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${paras}<w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr></w:body></w:document>`);return zip.generateAsync({type:'nodebuffer',compression:'DEFLATE'})}
async function makeXlsx(csv){const zip=new JSZip(),rows=parseCsvRows(csv),sheetRows=rows.map((row,ri)=>`<row r="${ri+1}">${row.map((v,ci)=>{const ref=`${columnName(ci+1)}${ri+1}`,num=String(v).trim();return /^-?\d+(?:\.\d+)?$/.test(num)?`<c r="${ref}"><v>${num}</v></c>`:`<c r="${ref}" t="inlineStr"><is><t xml:space="preserve">${xmlEscape(v)}</t></is></c>`}).join('')}</row>`).join('');zip.file('[Content_Types].xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>');zip.file('_rels/.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');zip.file('xl/workbook.xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Pothub Data" sheetId="1" r:id="rId1"/></sheets></workbook>');zip.file('xl/_rels/workbook.xml.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>');zip.file('xl/worksheets/sheet1.xml',`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>${sheetRows}</sheetData></worksheet>`);return zip.generateAsync({type:'nodebuffer',compression:'DEFLATE'})}
function makePdf(text){const lines=[];for(const raw of String(text||'').replace(/\r/g,'').split('\n')){const line=raw.replace(/[^\x20-\x7E]/g,'?');for(let i=0;i<Math.max(1,line.length);i+=88)lines.push(line.slice(i,i+88));}const body=lines.slice(0,52),ops=['BT','/F1 10 Tf','50 790 Td','14 TL',...body.map((line,i)=>`${i?'T* ':''}(${line.replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)')}) Tj`),'ET'].join('\n');const stream=Buffer.from(ops,'latin1');const objs=[Buffer.from('<< /Type /Catalog /Pages 2 0 R >>','latin1'),Buffer.from('<< /Type /Pages /Kids [3 0 R] /Count 1 >>','latin1'),Buffer.from('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','latin1'),Buffer.from('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>','latin1'),Buffer.concat([Buffer.from(`<< /Length ${stream.length} >>\nstream\n`,'latin1'),stream,Buffer.from('\nendstream','latin1')])];const chunks=[Buffer.from('%PDF-1.4\n%Pothub\n','latin1')],offsets=[0];let pos=chunks[0].length;objs.forEach((o,i)=>{offsets.push(pos);const part=Buffer.concat([Buffer.from(`${i+1} 0 obj\n`,'latin1'),o,Buffer.from('\nendobj\n','latin1')]);chunks.push(part);pos+=part.length});const xref=pos;let tail=`xref\n0 ${objs.length+1}\n0000000000 65535 f \n`;for(let i=1;i<offsets.length;i++)tail+=`${String(offsets[i]).padStart(10,'0')} 00000 n \n`;tail+=`trailer\n<< /Size ${objs.length+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;chunks.push(Buffer.from(tail,'latin1'));return Buffer.concat(chunks)}
app.post('/api/files/generate',async(req,res)=>{const s=await requireUser(req,res);if(!s)return;try{const i=z.object({prompt:z.string().min(8).max(8000),filename:z.string().min(1).max(120),format:z.string().min(1).max(24)}).parse(req.body);const filename=i.filename.replace(/[^a-zA-Z0-9._-]/g,'_').replace(/^\.+/,'').slice(0,100);if(!filename||filename==='.'||filename==='..'||filename.includes('..'))throw Error('Choose a safe filename.');const ext=(i.format||filename.split('.').pop()||'txt').toLowerCase().replace(/^\./,'');const supportedFormats=new Set(['txt','md','json','csv','html','htm','xml','yaml','yml','js','ts','jsx','tsx','css','sql','py','sh','svg','mermaid','pdf','docx','xlsx']);if(!supportedFormats.has(ext))throw Error('Supported formats include text/code, PDF, Word DOCX and Excel XLSX. Images, audio, video, PowerPoint and other binary formats need dedicated exporters.');const finalName=filename.toLowerCase().endsWith(`.${ext}`)?filename:`${filename}.${ext}`;const prompt=`Create one complete, valid file in the requested format. Return ONLY JSON with fields {"filename":"${finalName}","mimeType":"appropriate MIME type","content":"entire file content as text"}. Do not use markdown fences. Do not return explanations outside the JSON. If the requested format is binary and cannot be represented safely as text, return a clear text-based source representation instead and explain the limitation in the file content. Requested filename: ${finalName}. Format: ${ext}. ${ext==='xlsx'?'For XLSX, return CSV rows with a header row; the server converts them into a real Excel workbook.':ext==='docx'?'For DOCX, return document text with headings and paragraphs; the server packages it as a Word document.':ext==='pdf'?'For PDF, return plain text with headings and short paragraphs; the server converts it to a simple PDF.':''} User requirements: ${i.prompt}. Make the result complete, valid, and concise enough to fit the response. Never include secrets or claim that the file was executed or tested.`;const {result,cost}=await chargedModelJson(prompt,{userId:s.user.id,amount:15,reason:'Generate file',metadata:{format:ext,filename:finalName},req});const content=String(result.content||'');if(!content.trim()){await addCredits(s.user.id,15,`refund:${randomRef('empty-file')}`,'File generation returned empty content; refund');throw Error('The model returned an empty file. Credits were refunded.');}const binary=ext==='pdf'||ext==='docx'||ext==='xlsx';let outputBuffer=null;if(ext==='pdf')outputBuffer=makePdf(content);else if(ext==='docx')outputBuffer=await makeDocx(content);else if(ext==='xlsx')outputBuffer=await makeXlsx(content);const mime=String(result.mimeType||({json:'application/json',csv:'text/csv',html:'text/html',htm:'text/html',xml:'application/xml',svg:'image/svg+xml',md:'text/markdown',txt:'text/plain',yaml:'text/yaml',yml:'text/yaml',js:'text/javascript',ts:'text/plain',css:'text/css',sql:'application/sql',py:'text/x-python',sh:'text/plain',mermaid:'text/plain',pdf:'application/pdf',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}[ext]||'text/plain')).slice(0,120);res.json({ok:true,filename:finalName,format:ext,mimeType:mime,content,contentBase64:outputBuffer?outputBuffer.toString('base64'):null,contentSize:outputBuffer?outputBuffer.length:Buffer.byteLength(content),binary:!!outputBuffer,creditsSpent:15,creditsRemaining:cost.credits,warning:'Review the generated file before using it in production. AI content is not automatically validated or executed.'})}catch(e){err(res,e,e instanceof z.ZodError?422:400)}});
app.post('/api/repair/propose',async(req,res)=>{const s=await requireUser(req,res);if(!s)return;try{const input=z.object({repo:z.object({owner:z.string().min(1),name:z.string().min(1),defaultBranch:z.string().optional()}),issue:z.object({category:z.string(),title:z.string(),details:z.string().optional(),filePath:z.string().optional(),fixSummary:z.string().optional()}),logs:z.string().max(14000).optional()}).parse(req.body),balance=await getCredits(s.user.id);if(balance.credits<20)throw Error('Not enough credits. Buy a pack to continue.');const context=await repoContext(s,input.repo.owner,input.repo.name),target=input.issue.filePath||context.files[0]?.path,existing=context.files.find(f=>f.path===target)||context.files[0];if(!existing)throw Error('No suitable text file was found to propose a safe patch.');const prompt=`Create a conservative code repair proposal. Return ONLY JSON {"explanation":"short explanation","files":[{"path":"existing repository-relative path","content":"COMPLETE new file contents","reason":"why needed"}]}. Max 2 files, only modify files included in context, include complete file content, do not create credentials/secrets, do not alter env values, avoid unrelated refactors, return empty files if no safe fix. Never claim tests passed.\nRepository ${input.repo.owner}/${input.repo.name} branch ${context.branch}.\nIssue ${JSON.stringify(input.issue)}.\nTarget file ${JSON.stringify(existing)}.\nOther files ${JSON.stringify(context.files.filter(f=>f.path!==existing.path).slice(0,6))}.\nLogs ${redactSecrets(input.logs||'none')}`;const {result,cost}=await chargedModelJson(prompt,{userId:s.user.id,amount:20,reason:'Prepare repair',metadata:{repo:`${input.repo.owner}/${input.repo.name}`,issue:input.issue.title},req}),files=(Array.isArray(result.files)?result.files:[]).slice(0,2).map(f=>({path:String(f.path||''),content:String(f.content||''),reason:String(f.reason||'AI-proposed repair')})).filter(f=>f.path&&f.content&&f.content.length<90000&&context.files.some(c=>c.path===f.path));if(!files.length){await addCredits(s.user.id,20,`refund:${randomRef('empty-patch')}`,'No safe patch generated; credit refund');const remaining=await getCredits(s.user.id);return res.json({explanation:String(result.explanation||''),files,creditsReserved:0,creditsRemaining:remaining.credits,demo:remaining.demo,warning:'No safe patch could be generated; no credits were charged.'})}res.json({explanation:String(result.explanation||''),files,creditsReserved:20,creditsRemaining:cost.credits,demo:cost.demo,warning:'Review complete file contents before committing.'})}catch(e){err(res,e,e instanceof z.ZodError?422:400)}});
app.post('/api/github/commit-fix',async(req,res)=>{const s=await requireUser(req,res);if(!s)return;try{const i=z.object({owner:z.string().min(1),repo:z.string().min(1),baseBranch:z.string().min(1),commitMessage:z.string().min(4).max(160),files:z.array(z.object({path:z.string().min(1).max(240),content:z.string().max(90000)})).min(1).max(2)}).parse(req.body);for(const f of i.files)if(f.path.startsWith('/')||f.path.split('/').includes('..')||f.path.toLowerCase().includes('.env')||f.path.toLowerCase().includes('secret'))throw Error(`Blocked potentially sensitive or unsafe path: ${f.path}`);const branch=`pothub/repair-${new Date().toISOString().slice(0,10)}-${crypto.randomBytes(3).toString('hex')}`,base=await gh(s,`/repos/${i.owner}/${i.repo}/git/ref/heads/${encodeURIComponent(i.baseBranch)}`),parent=await gh(s,`/repos/${i.owner}/${i.repo}/git/commits/${base.object.sha}`),items=[];for(const f of i.files){const b=await gh(s,`/repos/${i.owner}/${i.repo}/git/blobs`,{method:'POST',body:JSON.stringify({content:f.content,encoding:'utf-8'})});items.push({path:f.path,mode:'100644',type:'blob',sha:b.sha})}const tree=await gh(s,`/repos/${i.owner}/${i.repo}/git/trees`,{method:'POST',body:JSON.stringify({base_tree:parent.tree.sha,tree:items})}),commit=await gh(s,`/repos/${i.owner}/${i.repo}/git/commits`,{method:'POST',body:JSON.stringify({message:i.commitMessage,tree:tree.sha,parents:[base.object.sha]})});await gh(s,`/repos/${i.owner}/${i.repo}/git/refs`,{method:'POST',body:JSON.stringify({ref:`refs/heads/${branch}`,sha:commit.sha})});res.json({ok:true,branch,commitSha:commit.sha,commitUrl:`https://github.com/${i.owner}/${i.repo}/commit/${commit.sha}`,branchUrl:`https://github.com/${i.owner}/${i.repo}/tree/${encodeURIComponent(branch)}`,files:i.files.map(f=>f.path),note:'Review and run checks before merging.'})}catch(e){err(res,e,e instanceof z.ZodError?422:400)}});
async function sendPushToUser(githubId,notification){
 if(!supabase)return;const {data:subs,error}=await supabase.from('notification_subscriptions').select('*').eq('github_id',String(githubId));if(error||!subs?.length)return;
 for(const sub of subs){try{if(sub.kind==='web'&&sub.subscription&&process.env.VAPID_PUBLIC_KEY&&process.env.VAPID_PRIVATE_KEY){const wp=(await import('web-push')).default;wp.setVapidDetails(process.env.VAPID_SUBJECT||'mailto:admin@example.com',process.env.VAPID_PUBLIC_KEY,process.env.VAPID_PRIVATE_KEY);await wp.sendNotification(sub.subscription,JSON.stringify({title:notification.title,body:notification.body,url:notification.url||'/',tag:notification.tag||notification.id||notification.title}))}else if(sub.kind==='android'&&process.env.FIREBASE_SERVICE_ACCOUNT_JSON){const admin=await import('firebase-admin');if(!admin.default.apps.length){const credential=admin.default.credential.cert(JSON.parse(process.env.FIREBASE_SERVICE_ACCOUNT_JSON));admin.default.initializeApp({credential})}await admin.default.messaging().send({token:sub.endpoint.slice(4),notification:{title:notification.title,body:notification.body},data:{url:notification.url||'/'}})}}catch(e){console.warn('Push delivery failed:',e?.code||e?.message||'unknown');if(String(e?.statusCode)==='404'||String(e?.statusCode)==='410')await supabase.from('notification_subscriptions').delete().eq('endpoint',sub.endpoint)}}
}
